using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
namespace LittleNotebook {public partial class MainWindow {
 Button miniPreviewEye;TextBlock miniClock;
 string FormatPuzzleTime(double seconds){var t=TimeSpan.FromSeconds(seconds);return ((int)t.TotalMinutes).ToString("00")+":"+t.Seconds.ToString("00")+"."+(t.Milliseconds/100);}
 string ExtraTitle(string key){switch(key){case "lights":return T("Light Garden","حديقة الضوء");case "queens":return T("Pocket Queens","ملكات الجيب");case "crates":return T("Crate Garden","حديقة الصناديق");case "pegs":return T("Pebble Solitaire","لعبة الحصى");case "untangle":return T("Thread Untangle","فك الخيوط");case "pour":return T("Colour Pour","قطرات الألوان");case "code":return T("Codebreaker","الرمز الخفي");case "domino":return T("Domino Patch","رقعة الدومينو");case "glide":return T("Marble Glide","انزلاق الكرة");default:return T("Flood Garden","حديقة الألوان");}}
 string ExtraInstructions(string key){switch(key){case "lights":return T("Turn every light off. Each press flips its neighbours too.","أطفئ كل الأضواء. كل ضغطة تقلب الخانة وجيرانها أيضاً.");case "queens":return T("Place one queen in each row. No queens may share a column or diagonal.","ضع ملكة في كل صف دون مشاركة عمود أو قطر.");case "crates":return T("Push every crate onto a leaf. You can push, but cannot pull.","ادفع كل صندوق إلى ورقة. يمكنك الدفع ولا يمكنك السحب.");case "pegs":return T("Jump over a neighbour into an empty hole. Leave just one pebble.","اقفز فوق حصاة مجاورة إلى حفرة فارغة حتى تبقى حصاة واحدة.");case "untangle":return T("Drag the paper pins until no threads cross. Keep pins apart.","اسحب الدبابيس حتى لا تتقاطع الخيوط مع إبقاء الدبابيس متباعدة.");case "pour":return T("Sort the drops. Each tube must be empty or hold four of the same colour.","رتّب القطرات. كل أنبوب فارغ أو يحتوي أربع قطرات من لون واحد.");case "code":return T("Find the hidden code. Solid dots: exact; hollow dots: colour in another place.","اكتشف الرمز. الدائرة الممتلئة: مكان صحيح؛ الفارغة: لون في مكان آخر.");case "domino":return T("Pair adjacent numbers into dominoes. Use each number pair only once.","صِل الأعداد المتجاورة لتكوين قطع دومينو دون تكرار أي زوج.");case "glide":return T("Slide the marble onto the leaf. It only stops at a wall or an edge.","حرّك الكرة إلى الورقة. لا تتوقف إلا عند جدار أو حافة.");default:return T("Grow the top-left patch until the whole garden shares its colour.","وسّع الرقعة أعلى اليسار حتى تصبح الحديقة كلها بلون واحد.");}}
 string ExtraControls(string key){if(key=="untangle")return T("Drag a pin · Undo reverses a drag · pause whenever you like","اسحب دبوساً · تراجع يعكس الحركة · يمكنك الإيقاف في أي وقت");if(key=="crates"||key=="glide")return T("Arrow keys / W A S D or click a direction · U / Ctrl+Z to undo","الأسهم أو W A S D أو انقر باتجاه الحركة · U أو Ctrl+Z للتراجع");if(key=="pour"||key=="pegs"||key=="domino")return T("Choose a source, then its destination · U / Ctrl+Z to undo","اختر المصدر ثم الوجهة · U أو Ctrl+Z للتراجع");if(key=="code")return T("Choose colours A–H or click · Enter checks your guess · U to undo","اختر الألوان بالحروف A–H أو بالنقر · Enter للتحقق · U للتراجع");return T("Click to play · arrow keys select, Enter uses a cell · U / Ctrl+Z to undo","انقر للعب · الأسهم للتحديد وEnter للاستخدام · U أو Ctrl+Z للتراجع");}
 void UndoExtra(){if(mini==null||mini.Extra==null||mini.Phase=="complete")return;if(mini.Extra.Undo()){mini.Phase="playing";mini.Moves=mini.Extra.Moves;if(overlay.Children.Count>0)CloseModal();RefreshMiniHud();miniSurface.InvalidateVisual();FocusMiniSurface();}}
 void RefreshExtraHud(){var b=mini.Extra;miniLives.Text="";miniCounter.Text=b.Moves+T(" moves"," حركات");if(b.Kind=="untangle")miniCounter.Text=b.Crossings()+T(" crossings"," تقاطعات");if(b.Kind=="code")miniCounter.Text=b.Guesses.Count+" / "+b.Limit+T(" guesses"," محاولات");if(b.Kind=="flood")miniCounter.Text=b.Moves+" / "+b.Limit+T(" changes"," تغييرات");if(b.Kind=="pegs")miniCounter.Text=b.Cells.Sum()+T(" pebbles left"," حصاة متبقية");miniStatus.Text=mini.Phase=="complete"?T("Nicely done!  ","أحسنت! ")+FormatPuzzleTime(mini.Elapsed)+" · "+mini.Moves+T(" moves"," حركات"):b.Message=="blocked"?T("That move is blocked. Try another, or undo.","هذه الحركة غير متاحة. جرّب غيرها أو تراجع."):b.Kind=="lights"?b.Cells.Sum()+T(" lights still glowing"," أضواء مضاءة"):b.Kind=="queens"?b.Cells.Sum()+" / "+b.W+T(" queens placed"," ملكات موضوعة"):b.Kind=="crates"?Enumerable.Range(0,b.Cells.Length).Count(i=>b.Goal[i]==1&&b.Cells[i]==1)+T(" crates on leaves"," صناديق على الأوراق"):b.Kind=="pour"?T("Select a tube, then a matching colour or an empty tube.","اختر أنبوباً ثم لوناً مطابقاً أو أنبوباً فارغاً."):b.Kind=="glide"?T("Plan your stops before you slide.","خطّط لنقاط التوقف قبل الانزلاق."):b.Kind=="code"?T("Colours may repeat. Feedback counts do not identify positions.","قد تتكرر الألوان. أعداد التلميحات لا تكشف مواضعها."):b.Kind=="domino"?T("Cross off every pair in the list below the board.","أكمل كل الأزواج في القائمة أسفل اللوحة."):b.Kind=="pegs"?T("One leap removes one pebble. Plan the last few jumps.","كل قفزة تزيل حصاة. خطّط للقفزات الأخيرة."):b.Kind=="untangle"?T("Red threads cross; green threads are clear.","الخيوط الحمراء متقاطعة والخضراء خالية."):T("Start in the top-left corner and expand your patch.","ابدأ من أعلى اليسار ووسّع رقعتك.");}
 bool ExtraKey(KeyEventArgs e){if(mini.Extra==null)return false;var b=mini.Extra;if(e.Key==Key.U||e.Key==Key.Z&&Keyboard.Modifiers==ModifierKeys.Control){if(!e.IsRepeat)UndoExtra();return true;}if(Keyboard.FocusedElement is Button)return false;int d=MiniDirection(e.Key);if(b.Kind=="crates"||b.Kind=="glide"){if(d<0)return false;if(e.IsRepeat&&mini.Elapsed-extraLastKey<.11)return true;extraLastKey=mini.Elapsed;if(b.Move(d)){mini.CheckExtra();RefreshMiniHud();miniSurface.InvalidateVisual();}return true;}if(b.Kind=="code"){if(e.Key>=Key.A&&e.Key<=Key.H){MiniPress(100+e.Key-Key.A);return true;}if(e.Key==Key.Enter){MiniPress(99);return true;}}if(d>=0&&b.Kind!="untangle"&&b.Kind!="pour"&&b.Kind!="code"){int next=MiniGrid.Next(b.Focus,d,b.W,b.H);if(next>=0)b.Focus=next;miniSurface.InvalidateVisual();return true;}if(e.Key==Key.Enter||e.Key==Key.Space){if(!e.IsRepeat)MiniPress(b.Kind=="flood"?b.Cells[b.Focus]:b.Focus);return true;}return false;}
 double extraLastKey=-1;
 void ShowMiniRecords(){string kind=Profile.Settings.SelectedMiniGame;Modal(MiniName(kind)+T(" · records"," · السجلات"),c=>{var list=new StackPanel{Width=590};if(kind=="stack")list.Children.Add(Text(T("High score: ","أعلى نتيجة: ")+Profile.StackBest,25,580));else if(kind=="mousedash")list.Children.Add(Text(T("Longest run: ","أطول محاولة: ")+FormatPuzzleTime(Profile.MiniGames[kind].BestSeconds),25,580));else {var record=Profile.MiniGames[kind];if(record.Results.Count==0)list.Children.Add(Text(T("Complete a puzzle to save its time and moves.","أكمل لغزاً لحفظ الوقت والحركات."),20,580));foreach(var result in record.Results.AsEnumerable().Reverse()){var row=Text(T("Level ","المستوى ")+result.Level+"   ·   "+FormatPuzzleTime(result.Seconds)+"   ·   "+result.Moves+T(" moves"," حركات"),19,580);row.Margin=new Thickness(6,8,6,8);list.Children.Add(row);}}var scroll=new ScrollViewer{Width=610,Height=345,Content=list,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};StylePaperScroll(scroll);Put(c,scroll,94,107);Btn(c,T("Close","إغلاق"),253,473,CloseModal,291,45);},560);}
 void ExtraFailure(){Modal(T("A fresh approach?","محاولة بطريقة أخرى؟"),c=>{Label(c,T("Your level is kept. Undo the last move, or restart this board.","يبقى مستواك محفوظاً. تراجع عن آخر حركة أو أعد اللوحة."),99,112,21,590);Btn(c,T("Undo last move","تراجع عن آخر حركة"),103,258,UndoExtra,280,48,true);Btn(c,T("Restart level","إعادة المستوى"),408,258,()=>StartMiniGame(mini.Kind),280,48);Btn(c,T("Back to minigames","العودة للألعاب المصغّرة"),215,326,BackToMiniGames,365,45);},420);}
 }
 public sealed partial class MiniGameBadge {
  static void DrawExtraBadge(DrawingContext dc,string kind,Palette p){Color c=MiniSurface.PuzzleColour(Array.IndexOf(ExtraPuzzle.Keys,kind));var brush=new SolidColorBrush(c);var pen=new Pen(new SolidColorBrush(p.Ink),1.4);dc.DrawRoundedRectangle(new SolidColorBrush(p.Paper),pen,new Rect(3,3,31,31),7,7);string mark=kind=="lights"?"☀":kind=="queens"?"♛":kind=="crates"?"▧":kind=="pegs"?"●":kind=="untangle"?"✣":kind=="pour"?"◒":kind=="code"?"✦":kind=="domino"?"⚄":kind=="glide"?"◉":"❀";var text=new FormattedText(mark,System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,new Typeface("Segoe UI Symbol"),25,brush,1);dc.DrawText(text,new Point(19-text.Width/2,18-text.Height/2));}
 }
 public sealed partial class MiniSurface {public static Color PuzzleColour(int index){return PuzzleColours[Math.Abs(index)%PuzzleColours.Length];}}
}
